SELECT CASE WHEN salary >= 122000 THEN 'HIGH' ELSE 'LOW' END AS salary_tier, DATE_TRUNC('MONTH', hire_date) AS activity_month, COUNT(CASE WHEN job_title = 'Engineer' THEN 1 END) AS engineer_count, STDDEV_SAMP(salary) AS salary_stddev, COUNT(*) FILTER (WHERE job_title = 'Designer') AS designer_rows, PERCENTILE_APPROX(salary, ARRAY(0.25, 0.5, 0.75)) AS salary_quartiles, GROUPING(CASE WHEN salary >= 122000 THEN 'HIGH' ELSE 'LOW' END) AS grouping_id FROM employees GROUP BY ROLLUP (CASE WHEN salary >= 122000 THEN 'HIGH' ELSE 'LOW' END, DATE_TRUNC('MONTH', hire_date)) ORDER BY engineer_count DESC NULLS FIRST
